                "p_value": round(p, 4) if p is not None else None,
            }

    # ── Overall ──
    all_f1 = [r["macro_f1"] for r in rows]
    all_bias = [r["abs_bias"] for r in rows]
    rho_all, p_all = _spearman(all_f1, all_bias)

