    print()

    fmt = f"{'topology':<14} {'n':>3}  {'ρ':>8}  {'p':>10}"
    print(fmt)
    print("-" * 40)
    for topo in TOPOS:
        t = per_topo[topo]
        rho_s = f"{t['spearman_rho']:+.4f}" if t["spearman_rho"] is not None else "   n/a"
